// Anonymous deployment readback. No credentials, customer data, provider requests or messages.
const origin='https://noody-ai-production.up.railway.app',webOrigin='https://brownnoodyai-sketch.github.io';
const paths=['/v1/settings/whatsapp/capacity','/v1/settings/website-reviews/pending'];
const results=[];
for(const path of paths){try{const r=await fetch(origin+path,{credentials:'omit',redirect:'error',signal:AbortSignal.timeout(10000)});await r.arrayBuffer();results.push({path,http:r.status,protected:[401,403].includes(r.status)});}catch{results.push({path,http:null,protected:false});}}
let reviewMounted=false,reviewHttp=null;try{const r=await fetch(origin+'/v1/public/reviews?kind=PRODUCT&id=00000000-0000-4000-8000-000000000000&island=AGATTI',{credentials:'omit',redirect:'error',signal:AbortSignal.timeout(10000)});reviewHttp=r.status;const data=await r.json();reviewMounted=r.status===404&&data.message==='LISTING_UNAVAILABLE';}catch{}
let ownerPostCors=false;try{const r=await fetch(origin+'/v1/auth/login',{method:'OPTIONS',credentials:'omit',redirect:'error',headers:{Origin:webOrigin,'Access-Control-Request-Method':'POST','Access-Control-Request-Headers':'Content-Type,Authorization'},signal:AbortSignal.timeout(10000)});ownerPostCors=r.ok&&r.headers.get('access-control-allow-origin')===webOrigin&&/(^|,)\s*POST\s*(,|$)/i.test(r.headers.get('access-control-allow-methods')||'');await r.arrayBuffer();}catch{}
let healthy=false;try{const r=await fetch(origin+'/health',{credentials:'omit',redirect:'error',signal:AbortSignal.timeout(10000)}),data=await r.json();healthy=r.ok&&data.status==='ok'&&data.dependencies?.postgres==='up'&&data.dependencies?.redis==='up';}catch{}
const report={checkedAt:new Date().toISOString(),centralApiHealthy:healthy,ownerRoutes:results,publicReviewApiMounted:reviewMounted,unknownListingReviewHttp:reviewHttp,ownerPostCors,listingBackendReady:healthy&&reviewMounted&&ownerPostCors&&results.every(r=>r.protected),actualMetaDeliveryVerified:false,durableInboxEnabledVerified:false,ownerAiProviderConfiguredVerified:false,note:'Anonymous readback proves route deployment and CORS, not owner login, paid AI availability, worker configuration or actual Meta delivery.'};
console.log(JSON.stringify(report,null,2));if(process.env.GITHUB_STEP_SUMMARY){const{appendFile}=await import('node:fs/promises');await appendFile(process.env.GITHUB_STEP_SUMMARY,'### Listing API deployment readback\n\n'+JSON.stringify(report,null,2)+'\n');}
if(!report.listingBackendReady)process.exitCode=1;
